+                describe_sel(g)
+            ));
+        }
+        for eb in &area.extra {
+            if eb.mode == BoundaryMode::Include
+                && let BoundaryShape::Picks(bps) = &eb.shape
+                && bps.iter().any(|s| s == g)
+            {
+                return Some(format!(
+                    "'Do not touch' item {} is also in an Include machining boundary - remove it from one list",
+                    describe_sel(g)
+                ));
+            }
+        }
+    }
