+/// The S and F words of a program, in order.
+fn s_and_f(nc: &str) -> Vec<String> {
+    nc.split_whitespace()
+        .filter(|w| (w.starts_with('S') || w.starts_with('F')) && w[1..].starts_with(|c: char| c.is_ascii_digit() || c == '.'))
+        .map(str::to_owned)
+        .collect()
+}
