+            let r = passes
+                .iter()
+                .map(|pass| {
+                    let Some((first, rest)) = pass.split_first() else {
+                        return Vec::new();
+                    };
+                    let walk = match fit {
+                        Some(tol) => fit_arcs(pass, tol),
+                        None => vec![Seg::Line(rest.to_vec())],
+                    };
+                    let (walk, t) = fillet_corners(&walk, *first, rho, ARC_FIT_TOL, &legal);
