+fn stepped_cutter() -> Cutter {
+    Cutter::flat(&ToolGeom {
+        radius: 3.0,
+        nose_radius: 0.0,
+        flute_len: 10.0,
+        shank_radius: 6.0,
+        shank_len: 12.0,
+        holder_radius: 15.0,
+        holder_len: 20.0,
+    })
