+
+fn seg_path(a: [f64; 3], b: [f64; 3]) -> Toolpath {
+    let mut pb = PathBuilder::new(Point3::new(a[0], a[1], a[2]));
+    pb.push(MoveKind::Feed, Point3::new(b[0], b[1], b[2]), Some(500.0));
+    pb.finish()
